import{_ as o,o as t,c as s,a2 as a}from"./chunks/framework.CCXDMzJr.js";const k=JSON.parse('{"title":"第 12 章 工具系统与执行管道","description":"","frontmatter":{},"headers":[],"relativePath":"ch12-tools.md","filePath":"ch12-tools.md","lastUpdated":null}'),d={name:"ch12-tools.md"};function i(c,e,l,n,r,h){return t(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="第-12-章-工具系统与执行管道" tabindex="-1">第 12 章 工具系统与执行管道 <a class="header-anchor" href="#第-12-章-工具系统与执行管道" aria-label="Permalink to &quot;第 12 章 工具系统与执行管道&quot;">​</a></h1><p><code>packages/core/tools</code>（约 5600 行）是 dsh 的工具中枢：<strong>作用域工具注册表 + 受保护执行管道</strong>。模型看到的每个工具（<code>read</code>、<code>bash</code>、<code>glob</code>、<code>grep</code>……）都注册在这里。</p><h2 id="_12-1-定位" tabindex="-1">12.1 定位 <a class="header-anchor" href="#_12-1-定位" aria-label="Permalink to &quot;12.1 定位&quot;">​</a></h2><p><code>docs/subsystems/tools.md</code> 与 SA1 笔记的核心结论：</p><ul><li>工具是<strong>作用域化</strong>的：注册进哪个 context，就只对那个作用域可见（全局工具 vs agent 预设工具）；</li><li>执行是<strong>受保护</strong>的：<code>tools/pre-execute</code> / <code>tools/execute</code> / <code>tools/post-execute</code> 三个 waterfall 让策略（权限、审批、沙箱包裹）可以拦截每次调用；</li><li>工具 schema 会<strong>自动加入提示词组装</strong>（经 <code>ctx.systemPrompt</code>）——注册一个工具 = 模型立刻可见（下个 step 起）；</li><li><code>packages/core/tools/src/types.ts</code> 向 session 的 <code>SessionEventMap</code> <strong>声明合并</strong>两个工具事件（<code>tool/call</code> 的配对事件，源码里唯一的反向类型注入），四包依赖链保持单向：<code>scope → system-prompt → session → tools</code>。</li></ul><h2 id="_12-2-tooldefinition-工具的-是什么" tabindex="-1">12.2 ToolDefinition：工具的&quot;是什么&quot; <a class="header-anchor" href="#_12-2-tooldefinition-工具的-是什么" aria-label="Permalink to &quot;12.2 ToolDefinition：工具的&quot;是什么&quot;&quot;">​</a></h2><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">interface</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ToolDefinition</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  schema</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ToolSchema</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            // 模型可见的 JSON Schema</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  execute</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">input</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">context</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Promise</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ToolExecutionResult</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 业务执行</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // 可选：最终内容回调、UI 呈现回调（presentation）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>defineTool</code> DSL 提供类型化 schema 构造（<code>ValueSchemaSpec</code> / <code>ParameterSchemaSpec</code>），避免手写 JSON Schema；还支持 Python 类型映射（<code>py-types.ts</code>）——工具 schema 可以同时面向 TS 与 Python 消费方。</p><p>工具注册的核心在 <code>ToolRuntime</code>（SA1 行号证据）：<code>register</code>（注册工具）、<code>restrict</code>（作用域限制）、<code>guard</code>（守卫）、<code>schemas()</code>（组装给模型的 schema 列表）、<code>execute</code>（执行入口）。</p><h2 id="_12-3-执行管道-三个-waterfall" tabindex="-1">12.3 执行管道：三个 waterfall <a class="header-anchor" href="#_12-3-执行管道-三个-waterfall" aria-label="Permalink to &quot;12.3 执行管道：三个 waterfall&quot;">​</a></h2><p><code>docs/tool-execution-pipeline.md</code> 定义了完整管道。关键事件（<code>tools/*</code> 域）：</p><table tabindex="0"><thead><tr><th>事件</th><th>模式</th><th>职责</th></tr></thead><tbody><tr><td><code>tools/pre-execute</code></td><td>waterfall</td><td>执行前策略：权限检查、审批、沙箱包裹、参数改写</td></tr><tr><td><code>tools/execute</code></td><td>waterfall</td><td>执行本身（默认调用 <code>definition.execute</code>）</td></tr><tr><td><code>tools/post-execute</code></td><td>waterfall</td><td>执行后处理：结果改写、审计、工具私有 meta 呈现</td></tr><tr><td><code>tools/register</code></td><td>emit</td><td>工具注册通知</td></tr></tbody></table><p>三个 waterfall 的 <code>next()</code> 语义一致：调用 <code>next()</code> 委派，不调用即接管（否决或替换）。审批系统的接入方式：<code>tools/pre-execute</code> 的监听者（审批插件）检查工具与参数，命中审批策略则挂起执行等待人工批准/拒绝（<code>docs/subsystems/approval.md</code>）。</p><h3 id="执行身份的不可变性" tabindex="-1">执行身份的不可变性 <a class="header-anchor" href="#执行身份的不可变性" aria-label="Permalink to &quot;执行身份的不可变性&quot;">​</a></h3><p>工具执行上下文（<code>ToolExecutionContext</code>）是<strong>不可变快照</strong>：工具名、参数、调用者 agent、作用域……在分发时冻结。取消通过 <code>ABORTED</code> / <code>ABORTED_BEFORE_DISPATCH</code> 两态表达：尚未分发的调用直接标记 before-dispatch，已分发的在取消时置 ABORTED——日志里每个 <code>tool/call</code> 都有闭合的 <code>tool/result</code>。</p><h2 id="_12-4-与循环的衔接" tabindex="-1">12.4 与循环的衔接 <a class="header-anchor" href="#_12-4-与循环的衔接" aria-label="Permalink to &quot;12.4 与循环的衔接&quot;">​</a></h2><p>第 11 章的调度器：模型返回 <code>tool/call*</code> → 循环按 model order 逐个 <code>tools/execute</code> → 每个调用写 <code>tool/call</code>（arguments 原样 JSON 字符串）与 <code>tool/result</code>（含 <code>meta</code>——工具私有、对核心不透明、必须 JSON 可序列化，<code>Session.append</code> 在源头校验）。</p><p><code>tool/result</code> 的 <code>meta</code> 是设计亮点：工具可以在结果里附加呈现载荷（如 <code>dsh-tool-fs</code> 的结果时上下文 diff），核心不解析它，但持久化日志原样保留——重放时 UI 能还原完全相同的卡片。<code>presentResult</code> 是工具读取自己 meta 的入口。</p><h2 id="_12-5-工具呈现-presentation" tabindex="-1">12.5 工具呈现（presentation） <a class="header-anchor" href="#_12-5-工具呈现-presentation" aria-label="Permalink to &quot;12.5 工具呈现（presentation）&quot;">​</a></h2><p><code>core/agent-tool-presentation</code> 与 <code>packages/extensions</code> 下的 UI 包：工具的调用卡片（<code>tool.call.toolview</code> Slot，第 17 章）由工具的呈现回调 + 客户端渲染器共同决定。<code>ToolPresentation</code> 类型声明工具可提供的 UI 形态（文本、卡片、图表……）。</p><h2 id="_12-6-code-mode-同一管道的复用" tabindex="-1">12.6 Code Mode：同一管道的复用 <a class="header-anchor" href="#_12-6-code-mode-同一管道的复用" aria-label="Permalink to &quot;12.6 Code Mode：同一管道的复用&quot;">​</a></h2><p><code>packages/core/tools/src/code-mode.ts</code>：<strong>Code Mode</strong>（模型以代码而非工具调用表达操作的执行模式）复用同一条受保护管道——代码里的文件操作、命令执行仍然经过 fs/sandbox 策略与审批。这保证&quot;无论模型用工具还是代码，安全边界一致&quot;。</p><h2 id="_12-7-工具注册的生命周期" tabindex="-1">12.7 工具注册的生命周期 <a class="header-anchor" href="#_12-7-工具注册的生命周期" aria-label="Permalink to &quot;12.7 工具注册的生命周期&quot;">​</a></h2><p>工具注册本身是 fiber effect：插件卸载 → 工具自动消失 → <code>schemas()</code> 不再包含它 → 下个 step 模型不再看到它。&quot;工具集随 preset 变化&quot;由此自然实现：不同 agent 的 scope context 注册不同工具集，互不干扰（第 13、16 章）。</p><h2 id="_12-8-小结" tabindex="-1">12.8 小结 <a class="header-anchor" href="#_12-8-小结" aria-label="Permalink to &quot;12.8 小结&quot;">​</a></h2><ul><li>工具 = schema + execute + 呈现；<code>defineTool</code> 类型化构造；</li><li>执行管道 = 三个 waterfall（pre/execute/post），策略在 pre 挂接，审批在其中；</li><li>工具注册即作用域化副作用；schema 自动进提示词组装；</li><li>Code Mode 复用同一受保护管道；</li><li>执行身份不可变；取消两态闭合日志。</li></ul><p>下一章：提示词组装与 scope 原语。</p>`,27)])])}const u=o(d,[["render",i]]);export{k as __pageData,u as default};
